import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();
        double ratio = (double) x / (double) y;
        long answerNumerator = 0;
        long answerDenominator = 1;
        double minDiff = Double.MAX_VALUE;

        for (long b = 1; b <= n; b++) {
            double val = ratio * b;
            long aFloor = (long) val;
            long aCeil = aFloor + 1;

            double diffFloor = Math.abs(ratio - (double) aFloor / b);
            double diffCeil = Math.abs((double) aCeil / b - ratio);

            if (diffFloor < minDiff) {
                minDiff = diffFloor;
                answerNumerator = aFloor;
                answerDenominator = b;
            }
            if (diffCeil < minDiff) {
                minDiff = diffCeil;
                answerNumerator = aCeil;
                answerDenominator = b;
            }
        }
        System.out.println(answerNumerator + "/" + answerDenominator);
        sc.close();
    }
}
